int checks=0;
void test(bool condition,const std::string& name){if(!condition)throw std::runtime_error(name);++checks;}
void near(double a,double b,double tol,const std::string& name){test(std::abs(a-b)<=tol,name);}
void rejects(const std::function<void()>& f,const std::string& name){bool ok=false;try{f();}catch(const std::exception&){ok=true;}test(ok,name);}
Material material(double cv=2.8e6,double k=16){return {"manufactured_constant","manufactured_single_phase","material-fixture","reference_fixed_volume",{{250,-50*cv,k,3e6},{300,0,k,3e6},{1000,700*cv,k,3e6}}};}
electrode_heat::Geometry geometry(int nx=8,int ny=2){electrode_heat::Geometry g;g.nx=nx;g.ny=ny;g.revision="fixed-reference-v1";g.electrode="upper";return g;}
Epoch epoch(const Coupler& c,double dt){return c.make_epoch(dt,"admitted-manufactured-em-stage");}
Transfer collection_event(const electrode_heat::Geometry& g,std::uint64_t id,double energy,double time=0){Transfer x;x.producer="native_collection";x.sequence=id;x.energy_owner="boundary-energy";x.owner_sequence=id;x.event_time_s=time;x.state_id="e";x.parent_id="inherited-unknown";x.channel_id="absorbed_incident_K";x.x=g.x0+.25*g.width;x.y=g.y0;x.incoming_K_J=energy;return x;}
bool same(const State& a,const State& b){if(a.T!=b.T||a.time!=b.time||a.revision!=b.revision||a.watermarks!=b.watermarks||a.cumulative!=b.cumulative||a.inventory.size()!=b.inventory.size())return false;for(std::size_t i=0;i<a.inventory.size();++i)if(a.inventory[i].hi!=b.inventory[i].hi||a.inventory[i].lo!=b.inventory[i].lo)return false;return true;}
void balances(const Trial& t){test(std::abs(t.budget().residual_J)<=t.budget().roundoff_bound_J,"thermal energy balance");}
Patch patch(Face f=Face::LowY,double N=5e14){Patch p;p.desorption_enabled=true;p.id="upper-gap-H2O";p.state_id="H2O-ground-manufactured";p.parent_id="one-adsorbed-H2O-pool";p.source_hash="source-fixture";p.face=f;p.initial_particles=N;p.mass_kg=18*1.66053906660e-27;p.attempt_s=1e10;p.activation_eV=.1;p.desorption_eV=1;p.internal_eV=.2;return p;}
std::vector<Draw> draws(){return {{.2,.3,.4,.15,.2,.25},{.4,.5,.6,.35,.4,.45},{.6,.7,.8,.65,.6,.65},{.8,.9,.1,.85,.8,.85}};}
