 Transfer n=collection_event(g,1,0);n.event_time_s=dep.state().time;n.producer="unified_emission";n.energy_owner="emission-energy";n.channel_id="complete_Nottingham";n.outgoing_K_J=.0001;n.reference_out_J=-.0002;n.work_function_reference_part_J=-.00005;n.complete_nottingham=true;n.nottingham_wall_J=.0001;auto nt=dep.prepare(epoch(dep,1e-9),zero,{n},{});near(nt.budget().thermal_delta_J,.0001,2e-12,"Nottingham heat charged once");near(nt.budget().work_function_reference_part_J,-.00005,0,"distinct material reference diagnostic");n.nottingham_wall_J=.0002;rejects([&]{dep.prepare(epoch(dep,1e-9),zero,{n},{});},"double counted Nottingham rejected");
