 auto a=dep.prepare(epoch(dep,1e-9),zero,{},{});auto b=dep.prepare(epoch(dep,1e-9),zero,{},{});test(dep.commit(std::move(a)),"first trial commits");test(!dep.commit(std::move(b)),"stale trial cannot commit");
 Coupler nonlinear(g,material(),{},300,"source-fixture");auto ml=material();ml.knots={{250,-50*2.8e6,16,3e6},{300,0,16,3e6},{350,50*2.8e6,16,3e6},{500,350*2.8e6,16,3e6}};Coupler nl(g,ml,{},300,"source-fixture");mfem::ConstantCoefficient src(75*2.8e6);auto nltrial=nl.prepare(epoch(nl,1.),src,{},{});for(double T:nltrial.state().T)near(T,362.5,1e-8,"bounded nonlinear enthalpy solve");balances(nltrial);
