 auto g=geometry();auto p=patch(Face::LowY,1e16);p.initial_low_particles=-.1;p.attempt_s=1e-10;p.activation_eV=0;Coupler tiny(g,material(),{p},300,"source-fixture");auto t=tiny.prepare(epoch(tiny,1e-10),zero,{}, {draws()});test(t.packets().size()==4&&t.state().inventory[0].hi==1e16&&t.state().inventory[0].lo<-.1,"sub-ULP positive release retains existing low-limb inventory debit");balances(t);
 p=patch(Face::LowY,1e6);p.attempt_s=1e30;p.activation_eV=0;Coupler exhausted(g,material(),{p},300,"source-fixture");auto a=exhausted.prepare(epoch(exhausted,1e-9),zero,{}, {draws()});test(a.state().inventory[0].hi==0&&a.state().inventory[0].lo==0,"source cannot exceed available finite inventory");test(exhausted.commit(std::move(a)),"depletion commit");auto b=exhausted.prepare(epoch(exhausted,1e-9),zero,{},std::vector<std::vector<Draw>>(1));test(b.packets().empty(),"depleted inventory emits no new parent");
